#!/bin/bash
# gen_scripts.sh [target ...]
#
# pgbench's extended ("prepared") protocol sends :variables as bind parameters,
# so a table name cannot come from -D.  Bake the target table into a
# per-target script instead; the numeric variable (:k / :qk) stays a variable.
set -eu
cd "$(dirname "$0")"

TARGETS=${*:-"avb_t_heap avb_t_btree avb_t_av avb_t_pgv"}

for t in $TARGETS; do
    cat > "ins_$t.sql" <<EOF
-- generated by gen_scripts.sh for $t
\set k random(1, :nk)
INSERT INTO $t (embedding) SELECT embedding FROM avb_pool WHERE k = :k;
EOF
    cat > "q_$t.sql" <<EOF
-- generated by gen_scripts.sh for $t
\set qk random(1, :nq)
SELECT id FROM $t
 ORDER BY embedding <-> (SELECT q FROM avb_qpool WHERE qk = :qk)
 LIMIT 10;
EOF
done
echo "generated scripts for: $TARGETS"
